patch.violet-button:
@media (pointer: fine) and (not (any-pointer: coarse)) {
	:host {
		--_auto-target-size: var(--_target-size-natural);
		--_auto-control-type-size: var(--_type-body-size);
	}
}
/* Chrome does not move under the pointer; colour answers it. */
.control:hover {
	transform: none;
	box-shadow: none;
}
.control:active {
	transform: none;
}
/* The filled actions are keys: they sit one step up and go flat when pressed. */
.control[data-appearance="primary"],
.control[data-appearance="danger"] {
	box-shadow: var(--_shadow-control);
}
.control[data-appearance="primary"]:active,
.control[data-appearance="danger"]:active {
	box-shadow: none;
}
/* Quiet is text until the pointer is on it: an outline made it read as disabled. */
.control[data-appearance="quiet"] {
	border-color: transparent;
}
.control[disabled] {
	opacity: 0.5;
	box-shadow: none;
}

