/* The mark was centred on the row and the label on its first line, so a label with
   supporting text sat above its mark. Both now sit on the first line. */
.root {
	gap: var(--_space-inline-md);
}
.content {
	box-sizing: border-box;
	gap: var(--_space-stack-2xs);
	align-content: start;
	padding-block: calc((var(--_target-size) - var(--_type-body-line)) / 2);
}
:host([inline]) .content {
	padding-block: 0;
}
