:host(:disabled) :is(.control-shell, .label),
:host([aria-disabled="true"]) :is(.control-shell, .label) {
	opacity: 0.5;
}
.box {
	/* Without this the box was 18px beside a 16px radio. */
	box-sizing: border-box;
	box-shadow: none;
}
.root:hover .input:not(:checked):not(:indeterminate):not(:disabled) + .box {
	border-color: var(--_field-border-hover);
}
.input:focus-visible + .box {
	box-shadow:
		0 0 0 2px var(--_surface-page),
		0 0 0 4px var(--_focus-ring);
}
/* The state colours are for messages; an invalid mark needs the field's 3:1 edge. */
:host([invalid]) .box {
	border-color: var(--color-field-border-invalid, var(--_danger-border));
}

