patch.violet-text-field:
@media (pointer: fine) and (not (any-pointer: coarse)) {
	:host {
		--_auto-target-size: var(--_target-size-natural);
		--_auto-control-label-size: var(--_type-label-size);
		--_auto-control-body-size: var(--_type-body-size);
		--_auto-control-caption-size: var(--_type-caption-size);
	}
}

/* ── Buttons ───────────────────────────────────────────────────────────── */
/* The fill is the field, and it goes toward the base: white in light, black in dark. Its edge
   is an inner cut: a hairline all round, and inside it, along the top, the 3:1 rule that finds
   the control with a small shadow under it, as if the field were let into the page. The rule is
   an inset shadow, not a border colour, so it thins to nothing round the corners where a
   coloured border would stop dead against the sides. Cards and buttons carry their shadow
   outside. The full outline comes back for focus and for an invalid value.
   The soft part is a literal until there is a shadow.well token. */
.control-frame {
	border-color: var(--_border-subtle);
	background: var(--color-field-background, var(--_surface-page));
	color: var(--color-field-text, var(--color-text-primary));
	box-shadow:
		inset 0 1px 0 var(--_field-border),
		var(--shadow-well, inset 0 2px 3px -1px rgb(0 0 0 / 0.1));
}
.control-frame:hover {
	border-color: var(--_border-subtle);
	box-shadow:
		inset 0 1px 0 var(--_field-border-hover),
		var(--shadow-well, inset 0 2px 3px -1px rgb(0 0 0 / 0.1));
}
.control-frame:focus-within,
.control-shell.open .control-frame {
	border-color: var(--color-field-border-focus, var(--_focus-ring));
	box-shadow:
		0 0 0 calc(var(--size-focus-ring-width, 2px) - 1px) var(--color-field-border-focus, var(--_focus-ring)),
		0 0 0 4px color-mix(in srgb, var(--_focus-ring) 20%, transparent);
	transform: none;
}
:host([invalid]) .control-frame {
	border-color: var(--_danger-border);
}
:host([readonly]) .control-frame {
	background: var(--color-field-background-readonly, var(--_surface-subtle));
}
:host([disabled]) .control-frame,
:host(:disabled) .control-frame {
	opacity: 0.5;
}
.control,
.input {
	color: var(--color-field-text, var(--color-text-primary));
}
.control::placeholder,
.input::placeholder {
	color: var(--color-field-placeholder, var(--_text-muted));
}
/* One gap above a control and one below it. */
.label {
	margin-block-end: calc(var(--_space-stack-xs) + var(--_space-stack-2xs));
}
.supporting,
.error {
	margin-block-start: calc(var(--_space-stack-xs) + var(--_space-stack-2xs));
}
/* These two have no error line of their own, so under an invalid value the supporting
   text is the reason: say it in the error colour. */
:host([invalid]) .supporting {
	color: var(--color-state-danger-text, var(--_text-muted));
}

